<?php
/**
 * Exportador v7 longitudinal por estudiante + curso.
 * - una fila = estudiante + curso + bimestre base cerrado;
 * - promedio del curso igual al portal: promedio por competencia x porcentaje;
 * - C=10, B=13, A=17, AD=20 para el cálculo ponderado, igual que my_grades_legacy;
 * - una nota vacía nunca se convierte en cero;
 * - excluye periodos con cobertura anormalmente baja dentro del mismo año;
 * - carga datos por bimestre en bloques para evitar consultas N+1.
 */
if(PHP_SAPI!=='cli'){fwrite(STDERR,"Solo CLI.\n");exit(1);}
require_once __DIR__.'/../edusync/db_connect.php';
require_once __DIR__.'/../edusync/includes/predictive_risk.php';

$options=getopt('',['school:','year::','output::','min-relative-coverage::']);
$schoolId=(int)($options['school']??0);
$yearFilter=isset($options['year'])&&$options['year']!==false&&$options['year']!==''?(int)$options['year']:null;
$output=(string)($options['output']??(__DIR__.'/../storage/course_risk_dataset.csv'));
$minRelativeCoverage=(float)($options['min-relative-coverage']??0.25);
if($minRelativeCoverage<=0||$minRelativeCoverage>1)$minRelativeCoverage=0.25;
if($schoolId<=0){fwrite(STDERR,"Falta --school=<ID_REAL>.\n");exit(1);}
if(!isset($conn)||!($conn instanceof mysqli)){fwrite(STDERR,"Sin conexión MySQL.\n");exit(1);}
@set_time_limit(0);

function crw_progress(string $text): void {echo '['.date('H:i:s').'] '.$text."\n";if(function_exists('ob_flush'))@ob_flush();flush();}
function crw_val($v){return$v===null||$v===''?'':round((float)$v,6);}
function crw_norm(string $value): string {$value=trim($value);if(function_exists('iconv')){$x=@iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$value);if($x!==false)$value=$x;}$value=mb_strtolower($value,'UTF-8');return trim((string)preg_replace('/\s+/',' ',preg_replace('/[^a-z0-9]+/u',' ',$value)));}
function crw_ctx_key(int $courseId,string $level,string $grade,string $section): string {return$courseId.'|'.crw_norm($level).'|'.preg_replace('/\D+/','',$grade).'|'.crw_norm($section?:'U');}
function crw_grade_score($grade): ?float {$v=strtoupper(trim((string)$grade));if($v==='')return null;$n=str_replace(',','.',$v);if(is_numeric($n))return max(0.0,min(20.0,(float)$n));$map=['C'=>10.0,'B'=>13.0,'A'=>17.0,'AD'=>20.0];return$map[$v]??null;}
function crw_grade_low($grade): bool {$v=strtoupper(trim((string)$grade));if($v==='')return false;if($v==='C')return true;$n=str_replace(',','.',$v);return is_numeric($n)&&(float)$n<edu_predictive_critical_threshold();}
function crw_std(array $values): ?float {$v=array_values(array_filter($values,static fn($x)=>$x!==null&&is_numeric($x)));$n=count($v);if(!$n)return null;$m=array_sum($v)/$n;$ss=0.0;foreach($v as $x)$ss+=((float)$x-$m)**2;return sqrt($ss/$n);}
function crw_slope(array $values): ?float {$v=array_values(array_filter($values,static fn($x)=>$x!==null&&is_numeric($x)));$n=count($v);if($n<2)return null;$mx=($n-1)/2;$my=array_sum($v)/$n;$num=0.0;$den=0.0;foreach($v as $i=>$y){$dx=$i-$mx;$num+=$dx*((float)$y-$my);$den+=$dx*$dx;}return$den>0?$num/$den:null;}
function crw_years(mysqli $conn,int $schoolId,?int $yearId): array {$sql='SELECT id,year,start_date,end_date,is_active FROM academic_year WHERE school_id=?'.($yearId?' AND id=?':'').' ORDER BY start_date,id';$stmt=$conn->prepare($sql);if(!$stmt)return[];if($yearId)$stmt->bind_param('ii',$schoolId,$yearId);else$stmt->bind_param('i',$schoolId);$stmt->execute();$res=$stmt->get_result();$rows=[];while($r=$res->fetch_assoc())$rows[]=$r;$stmt->close();return$rows;}
function crw_eval_date_col(mysqli $conn): ?string {foreach(['evaluation_date','date'] as $col)if(edu_predictive_column_exists($conn,'evaluations',$col))return$col;return null;}
function crw_load_attendance(mysqli $conn,int $schoolId,array $studentIds,string $cutoffDate,int $windowDays=30): array {$out=[];$studentIds=array_values(array_unique(array_filter(array_map('intval',$studentIds))));if(!$studentIds||!edu_predictive_table_exists($conn,'asistencia'))return$out;$end=date('Y-m-d',strtotime($cutoffDate));$start=date('Y-m-d',strtotime($end.' -'.(max(7,min(120,$windowDays))-1).' days'));$cancel=edu_predictive_column_exists($conn,'asistencia','is_cancelled')?' AND COALESCE(a.is_cancelled,0)=0':'';foreach(array_chunk($studentIds,800) as $chunk){$ids=implode(',',array_map('intval',$chunk));$sql="SELECT a.student_id,a.fecha,CASE WHEN SUM(LOWER(TRIM(a.estado))='tarde')>0 THEN 'Tarde' WHEN SUM(LOWER(TRIM(a.estado)) IN ('presente','normal','temprano'))>0 THEN 'Presente' WHEN SUM(LOWER(TRIM(a.estado))='permiso')>0 THEN 'Permiso' WHEN SUM(LOWER(TRIM(a.estado)) IN ('ausente justificada','ausencia justificada'))>0 THEN 'Ausente Justificada' ELSE 'Ausente' END estado FROM asistencia a INNER JOIN student s ON s.id=a.student_id AND s.school_id=? WHERE a.student_id IN ($ids) AND a.tipo='Entrada' AND a.fecha BETWEEN ? AND ? $cancel GROUP BY a.student_id,a.fecha";$stmt=$conn->prepare($sql);if(!$stmt)continue;$stmt->bind_param('iss',$schoolId,$start,$end);$stmt->execute();$res=$stmt->get_result();while($r=$res->fetch_assoc())$out[(int)$r['student_id']][(string)$r['fecha']]=(string)$r['estado'];$stmt->close();}return$out;}
function crw_att(array $days): array {$present=0;$late=0;$absent=0;$records=count($days);foreach($days as $state){if($state==='Presente')$present++;elseif($state==='Tarde')$late++;elseif($state==='Ausente')$absent++;}return['attendance_rate_30d'=>$records?(($present+$late)/$records)*100.0:null,'late_30d'=>$records?(float)$late:null,'absent_30d'=>$records?(float)$absent:null,'attendance_records_30d'=>$records];}
function crw_weighted_mean(array $byCompetency,array $weights): ?float {$sum=0.0;$used=0;foreach($byCompetency as $cid=>$scores){if(!$scores)continue;$avg=array_sum($scores)/count($scores);$weight=(float)($weights[$cid]??1.0);$sum+=$avg*$weight;$used++;}return$used?$sum:null;}

function crw_load_period(mysqli $conn,int $schoolId,int $yearId,int $bimester,?string $cutoffDate): array {
    $hasTcYear=edu_predictive_column_exists($conn,'teacher_courses','academic_year_id');$hasEYear=edu_predictive_column_exists($conn,'evaluations','academic_year_id');$hasStatus=edu_predictive_column_exists($conn,'evaluations','status');$dateCol=crw_eval_date_col($conn);$dateExpr=$dateCol!==null?"DATE(e.`$dateCol`)":"NULL";$dateSelect=$dateExpr." evaluation_date";$dateOrder=$dateCol!==null?$dateExpr.",e.id":"e.id";$where=['tc.school_id=?','CAST(e.bimestre AS UNSIGNED)=?'];$types='ii';$params=[$schoolId,$bimester];if($hasTcYear){$where[]='tc.academic_year_id=?';$types.='i';$params[]=$yearId;}if($hasEYear){$where[]='e.academic_year_id=?';$types.='i';$params[]=$yearId;}if($hasStatus)$where[]="COALESCE(e.status,'Activa')<>'Anulada'";
    $sql="SELECT e.id evaluation_id,tc.course_id,COALESCE(NULLIF(TRIM(ac.name),''),'Curso') course_name,ac.level,tc.grado,COALESCE(NULLIF(TRIM(tc.seccion),''),'U') seccion,ec.competencia_id,COALESCE(gcc.percentage,100) competencia_percentage,$dateSelect FROM evaluations e INNER JOIN teacher_courses tc ON tc.id=e.teacher_course_id INNER JOIN academic_courses ac ON ac.id=tc.course_id INNER JOIN evaluation_competencias ec ON ec.evaluation_id=e.id LEFT JOIN general_course_competencies gcc ON gcc.id=ec.competencia_id WHERE ".implode(' AND ',$where)." ORDER BY $dateOrder,ec.competencia_id";
    $stmt=$conn->prepare($sql);if(!$stmt)throw new RuntimeException('No pude cargar definiciones: '.$conn->error);edu_predictive_bind($stmt,$types,$params);$stmt->execute();$res=$stmt->get_result();$defs=[];$evalCtx=[];while($r=$res->fetch_assoc()){$key=crw_ctx_key((int)$r['course_id'],(string)$r['level'],(string)$r['grado'],(string)$r['seccion']);$r['course_id']=(int)$r['course_id'];$r['competencia_id']=(int)$r['competencia_id'];$r['evaluation_id']=(int)$r['evaluation_id'];$r['weight']=max(0.0,(float)$r['competencia_percentage']/100.0);$defs[$key][]=$r;$evalCtx[$r['evaluation_id']]=$key;}$stmt->close();if(!$evalCtx)return['metrics'=>[],'student_meta'=>[],'date_available'=>$dateCol!==null];
    $studentMeta=[];$gradeMap=[];$studentContexts=[];foreach(array_chunk(array_keys($evalCtx),700) as $chunk){$idSql=implode(',',array_map('intval',$chunk));$gsql="SELECT eg.student_id,eg.evaluation_id,eg.competencia_id,eg.grade,s.name,s.id_no,s.nivel,s.grado,s.seccion FROM evaluation_grades eg INNER JOIN student s ON s.id=eg.student_id AND s.school_id=? WHERE eg.evaluation_id IN ($idSql)";$gst=$conn->prepare($gsql);if(!$gst)continue;$gst->bind_param('i',$schoolId);$gst->execute();$gr=$gst->get_result();while($r=$gr->fetch_assoc()){$sid=(int)$r['student_id'];$eid=(int)$r['evaluation_id'];$cid=(int)$r['competencia_id'];$gradeMap[$sid][$eid][$cid]=$r['grade'];$studentMeta[$sid]=['id'=>$sid,'name'=>(string)$r['name'],'id_no'=>(string)($r['id_no']??''),'nivel'=>(string)$r['nivel'],'grado'=>(string)$r['grado'],'seccion'=>(string)$r['seccion']];if(isset($evalCtx[$eid]))$studentContexts[$sid][$evalCtx[$eid]]=true;}$gst->close();}
    $attendance=$cutoffDate?crw_load_attendance($conn,$schoolId,array_keys($studentContexts),$cutoffDate,30):[];$raw=[];$classAgg=[];
    foreach($studentContexts as $sid=>$contexts){$att=crw_att($attendance[$sid]??[]);foreach(array_keys($contexts) as $key){if(empty($defs[$key]))continue;$grades=[];$allScores=[];$byComp=[];$weights=[];$low=0;$missing=0;$evalSeen=[];$courseId=0;$courseName='Curso';$byEval=[];$evalOrder=[];
        foreach($defs[$key] as $d){$courseId=(int)$d['course_id'];$courseName=(string)$d['course_name'];$eid=(int)$d['evaluation_id'];$cid=(int)$d['competencia_id'];$weights[$cid]=(float)$d['weight'];$evalSeen[$eid]=true;$evalOrder[$eid]=['date'=>(string)($d['evaluation_date']??''),'id'=>$eid];$grade=trim((string)($gradeMap[$sid][$eid][$cid]??''));if($grade===''){$missing++;continue;}$score=crw_grade_score($grade);if($score===null)continue;$byComp[$cid][]=$score;$byEval[$eid][]=$score;$allScores[]=$score;$grades[]=$grade;if(crw_grade_low($grade))$low++;}
        if(!$allScores)continue;$mean=crw_weighted_mean($byComp,$weights);if($mean===null)continue;$expected=count($defs[$key]);$graded=count($allScores);
        $evalMeans=[];foreach($byEval as $eid=>$vals)if($vals)$evalMeans[]=['id'=>(int)$eid,'date'=>$evalOrder[$eid]['date']??'','mean'=>array_sum($vals)/count($vals)];usort($evalMeans,static function($a,$b){$ad=(string)$a['date'];$bd=(string)$b['date'];if($ad!==''&&$bd!==''&&$ad!==$bd)return strcmp($ad,$bd);return(int)$a['id']<=>(int)$b['id'];});$evalValues=array_map(static fn($x)=>(float)$x['mean'],$evalMeans);$lastEval=$evalValues?end($evalValues):null;$recent=$evalValues?array_slice($evalValues,-3):[];$evalLow=0;$evalTrailing=0;foreach($evalValues as $v)if($v<edu_predictive_critical_threshold())$evalLow++;for($i=count($evalValues)-1;$i>=0;$i--){if($evalValues[$i]<edu_predictive_critical_threshold())$evalTrailing++;else break;}
        $compMeans=[];$criticalComp=0;$criticalWeight=0.0;$usedWeight=0.0;foreach($byComp as $cid=>$vals){if(!$vals)continue;$cm=array_sum($vals)/count($vals);$compMeans[]=$cm;$w=(float)($weights[$cid]??1.0);$usedWeight+=$w;if($cm<edu_predictive_critical_threshold()){$criticalComp++;$criticalWeight+=$w;}}
        $m=array_merge(['student_id'=>(int)$sid,'course_id'=>$courseId,'course_name'=>$courseName,'course_mean_current'=>$mean,'distance_to_critical'=>$mean-edu_predictive_critical_threshold(),'graded_cells'=>$graded,'expected_cells'=>$expected,'missing_grade_cells'=>$missing,'low_grade_cells'=>$low,'low_grade_rate_current'=>$graded?$low/$graded:null,'missing_grade_rate_current'=>$expected?$missing/$expected:null,'evaluations_count_current'=>count($evalSeen),'grades'=>$grades,'evaluation_mean_last'=>$lastEval,'evaluation_mean_recent3'=>$recent?array_sum($recent)/count($recent):null,'evaluation_trend_current'=>crw_slope($evalValues),'evaluation_std_current'=>crw_std($evalValues),'low_evaluation_rate_current'=>$evalValues?$evalLow/count($evalValues):null,'consecutive_low_evaluations_current'=>(float)$evalTrailing,'competencies_graded_current'=>(float)count($compMeans),'critical_competency_count_current'=>(float)$criticalComp,'critical_competency_rate_current'=>$compMeans?$criticalComp/count($compMeans):null,'critical_competency_weight_rate_current'=>$usedWeight>0?$criticalWeight/$usedWeight:null,'min_competency_mean_current'=>$compMeans?min($compMeans):null,'competency_std_current'=>crw_std($compMeans),'missing_eval_absence_overlap'=>null,'evaluation_date_available'=>$dateCol!==null],$att);$raw[$sid.'|'.$courseId]=$m;if(!isset($classAgg[$key]))$classAgg[$key]=['cell_scores'=>[],'low'=>0,'student_means'=>[]];foreach($allScores as $score)$classAgg[$key]['cell_scores'][]=$score;$classAgg[$key]['low']+=$low;$classAgg[$key]['student_means'][$sid]=$mean;
    }}
    $class=[];foreach($classAgg as $key=>$a){$means=$a['student_means'];$critical=0;foreach($means as $m)if($m<edu_predictive_critical_threshold())$critical++;$class[$key]=['class_course_mean_current'=>$means?array_sum($means)/count($means):null,'class_low_grade_rate_current'=>$a['cell_scores']?$a['low']/count($a['cell_scores']):null,'class_students_critical_rate'=>$means?$critical/count($means):null,'class_graded_cells'=>count($a['cell_scores']),'class_students_with_data'=>count($means)];}
    foreach($raw as &$m){$sid=(int)$m['student_id'];$meta=$studentMeta[$sid]??[];$key=crw_ctx_key((int)$m['course_id'],(string)($meta['nivel']??''),(string)($meta['grado']??''),(string)($meta['seccion']??'U'));$cl=$class[$key]??['class_course_mean_current'=>null,'class_low_grade_rate_current'=>null,'class_students_critical_rate'=>null,'class_graded_cells'=>0,'class_students_with_data'=>0];$m=array_merge($m,$cl);$m['student_vs_class_mean']=$m['class_course_mean_current']===null?null:$m['course_mean_current']-(float)$m['class_course_mean_current'];}unset($m);return['metrics'=>$raw,'student_meta'=>$studentMeta,'date_available'=>$dateCol!==null];
}
function crw_identity_key(array $meta): string {$dni=trim((string)($meta['id_no']??''));if($dni!=='')return'dni:'.$dni;return'name:'.crw_norm((string)($meta['name']??''));}
function crw_prior_features(array $meta,string $courseName,int $sourceBimester,array $bundle): array {
    $course=crw_norm($courseName);$entries=(array)($bundle['student'][crw_identity_key($meta).'|'.$course]??[]);$courseEntries=(array)($bundle['course'][$course]??[]);$out=['prior_years_periods_available'=>(float)count($entries),'prior_years_mean'=>null,'prior_years_last_mean'=>null,'prior_years_slope'=>null,'prior_years_critical_rate'=>null,'prior_years_last_critical'=>null,'prior_years_same_bimester_mean'=>null,'prior_years_persistence_after_critical_rate'=>null,'course_historical_mean'=>null,'course_historical_critical_rate'=>null,'course_historical_periods_available'=>(float)count($courseEntries)];
    if($entries){$means=array_map(static fn($x)=>(float)$x['mean'],$entries);$crit=0;$trans=0;$stay=0;$same=null;foreach($entries as $e){if($e['mean']<edu_predictive_critical_threshold())$crit++;if((int)$e['bimester']===$sourceBimester)$same=(float)$e['mean'];}for($i=0;$i<count($entries)-1;$i++){if($entries[$i]['mean']>=edu_predictive_critical_threshold())continue;$trans++;if($entries[$i+1]['mean']<edu_predictive_critical_threshold())$stay++;}$last=end($entries);$out['prior_years_mean']=array_sum($means)/count($means);$out['prior_years_last_mean']=(float)$last['mean'];$out['prior_years_slope']=crw_slope($means);$out['prior_years_critical_rate']=$crit/count($entries);$out['prior_years_last_critical']=$last['mean']<edu_predictive_critical_threshold()?1.0:0.0;$out['prior_years_same_bimester_mean']=$same;$out['prior_years_persistence_after_critical_rate']=$trans?$stay/$trans:null;}
    if($courseEntries){$vals=array_map(static fn($x)=>(float)$x['mean'],$courseEntries);$crit=0;foreach($vals as $v)if($v<edu_predictive_critical_threshold())$crit++;$out['course_historical_mean']=array_sum($vals)/count($vals);$out['course_historical_critical_rate']=$crit/count($vals);}
    return$out;
}

$features=['course_mean_current','distance_to_critical','course_trend','previous_course_available','previous_course_mean','previous_course_critical','current_course_critical','consecutive_critical_periods','critical_period_rate_same_year','same_year_mean','same_year_min_mean','same_year_course_slope','same_year_periods_available','low_grade_rate_current','missing_grade_rate_current','evaluations_count_current','evaluation_mean_last','evaluation_mean_recent3','evaluation_trend_current','evaluation_std_current','low_evaluation_rate_current','consecutive_low_evaluations_current','competencies_graded_current','critical_competency_count_current','critical_competency_rate_current','critical_competency_weight_rate_current','min_competency_mean_current','competency_std_current','attendance_rate_30d','attendance_trend_same_year','late_30d','absent_30d','class_course_mean_current','class_low_grade_rate_current','class_students_critical_rate','student_vs_class_mean','prior_years_periods_available','prior_years_mean','prior_years_last_mean','prior_years_slope','prior_years_critical_rate','prior_years_last_critical','prior_years_same_bimester_mean','prior_years_persistence_after_critical_rate','course_historical_mean','course_historical_critical_rate','course_historical_periods_available'];
$headers=array_merge(['school_id','academic_year_id','academic_year','student_id','student_key','nivel','grado','seccion','course_id','course_name','bimester','target_bimester','cutoff_date'],$features,['graded_cells','expected_cells','missing_eval_absence_overlap','evaluation_date_available','target_course_critical']);$dir=dirname($output);if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir)){fwrite(STDERR,"No pude crear $dir.\n");exit(1);}$fh=fopen($output,'wb');if(!$fh){fwrite(STDERR,"No pude crear $output.\n");exit(1);}fputcsv($fh,$headers);
$rows=0;$positive=0;$negative=0;$pairs=[];$courses=[];$missingAttendance=0;$missingGrades=0;$dateOverlapAvailable=0;$skippedTarget=0;$uniqueStudents=[];$sparse=[];$priorBundle=['student'=>[],'course'=>[]];$years=crw_years($conn,$schoolId,$yearFilter);if(!$years){fclose($fh);fwrite(STDERR,"No encontré años académicos.\n");exit(1);}crw_progress('Iniciando exportación v7 longitudinal ponderada. Años encontrados: '.count($years));
foreach($years as $year){$yearId=(int)$year['id'];$yearLabel=(string)($year['year']??$yearId);crw_progress("Año $yearLabel (ID $yearId): revisando cierres...");$closures=[];$periodData=[];$counts=[];for($b=1;$b<=4;$b++){$closures[$b]=edu_predictive_bimester_closure($conn,$schoolId,$yearId,$b);if(!empty($closures[$b]['closed'])){crw_progress('  Cargando '.edu_predictive_bimester_label($b).' bimestre cerrado...');$periodData[$b]=crw_load_period($conn,$schoolId,$yearId,$b,$closures[$b]['date']??null);$counts[$b]=count($periodData[$b]['metrics']);crw_progress('    Cursos-alumno con datos: '.$counts[$b]);}}$maxCount=$counts?max($counts):0;$valid=[];foreach($counts as $b=>$count){$ratio=$maxCount>0?$count/$maxCount:0;$valid[$b]=$ratio>=$minRelativeCoverage;if(!$valid[$b]){$sparse[]="$yearLabel ".edu_predictive_bimester_label((int)$b)." ($count/$maxCount)";crw_progress('    OMITIDO para entrenamiento: cobertura anormalmente baja ('.number_format($ratio*100,1).'%).');}}
    for($b=1;$b<=3;$b++){if(empty($valid[$b])||empty($valid[$b+1])||empty($closures[$b]['date']))continue;$before=$rows;crw_progress('  Generando par '.edu_predictive_bimester_label($b).'→'.edu_predictive_bimester_label($b+1).'...');foreach($periodData[$b]['metrics'] as $key=>$current){if(!isset($periodData[$b+1]['metrics'][$key])){$skippedTarget++;continue;}$target=$periodData[$b+1]['metrics'][$key];$history=[];for($hb=1;$hb<=$b;$hb++){if(empty($valid[$hb])||empty($periodData[$hb]['metrics'][$key]))continue;$history[]=$periodData[$hb]['metrics'][$key];}$previous=count($history)>=2?$history[count($history)-2]:null;$means=array_map(static fn($p)=>$p['course_mean_current'],$history);$prevMean=$previous['course_mean_current']??null;$prevAtt=$previous['attendance_rate_30d']??null;$threshold=edu_predictive_critical_threshold();$criticalPeriods=0;$trailing=0;foreach($means as $mv)if($mv!==null&&(float)$mv<$threshold)$criticalPeriods++;for($ti=count($means)-1;$ti>=0;$ti--){if($means[$ti]!==null&&(float)$means[$ti]<$threshold)$trailing++;else break;}$f=$current;$f['course_trend']=$prevMean!==null?$current['course_mean_current']-$prevMean:0.0;$f['previous_course_available']=$prevMean!==null?1.0:0.0;$f['previous_course_mean']=$prevMean;$f['previous_course_critical']=$prevMean!==null&&(float)$prevMean<$threshold?1.0:0.0;$f['current_course_critical']=(float)$current['course_mean_current']<$threshold?1.0:0.0;$f['consecutive_critical_periods']=(float)$trailing;$f['critical_period_rate_same_year']=$means?$criticalPeriods/count($means):null;$f['same_year_mean']=$means?array_sum($means)/count($means):null;$f['same_year_min_mean']=$means?min($means):null;$f['same_year_course_slope']=crw_slope($means);$f['same_year_periods_available']=(float)count($history);$f['attendance_trend_same_year']=($current['attendance_rate_30d']!==null&&$prevAtt!==null)?(float)$current['attendance_rate_30d']-(float)$prevAtt:null;$meta=$periodData[$b]['student_meta'][(int)$current['student_id']]??[];$f=array_merge($f,crw_prior_features($meta,(string)$current['course_name'],$b,$priorBundle));$line=[$schoolId,$yearId,$yearLabel,(int)$current['student_id'],crw_identity_key($meta),(string)($meta['nivel']??''),(string)($meta['grado']??''),(string)($meta['seccion']??''),(int)$current['course_id'],(string)$current['course_name'],$b,$b+1,(string)$closures[$b]['date']];foreach($features as $feature)$line[]=crw_val($f[$feature]??null);$line[]=(int)$f['graded_cells'];$line[]=(int)$f['expected_cells'];$line[]=crw_val($f['missing_eval_absence_overlap']??null);$line[]=!empty($f['evaluation_date_available'])?1:0;$targetCritical=(float)$target['course_mean_current']<edu_predictive_critical_threshold()?1:0;$line[]=$targetCritical;fputcsv($fh,$line);$rows++;$targetCritical?$positive++:$negative++;$pairs[$b.'->'.($b+1)]=($pairs[$b.'->'.($b+1)]??0)+1;$courses[(string)$current['course_name']]=($courses[(string)$current['course_name']]??0)+1;$uniqueStudents[crw_identity_key($meta)]=true;if((int)($f['attendance_records_30d']??0)===0)$missingAttendance++;if((int)($f['missing_grade_cells']??0)>0)$missingGrades++;if(!empty($f['evaluation_date_available']))$dateOverlapAvailable++;}crw_progress('    Filas agregadas: '.($rows-$before).' | acumuladas: '.$rows);}foreach($periodData as $pb=>$pdata){if(empty($valid[$pb]))continue;foreach($pdata['metrics'] as $hm){$sid=(int)$hm['student_id'];$meta=$pdata['student_meta'][$sid]??null;if(!$meta)continue;$course=crw_norm((string)$hm['course_name']);$entry=['year_id'=>$yearId,'bimester'=>(int)$pb,'mean'=>(float)$hm['course_mean_current']];$priorBundle['student'][crw_identity_key($meta).'|'.$course][]=$entry;$priorBundle['course'][$course][]=$entry;}}}
fclose($fh);arsort($courses);echo "\nDataset por curso creado: $output\n";echo "Esquema: v7 longitudinal estudiante + curso + bimestre | historial multianual + evaluaciones + competencias\n";echo "Filas curso-periodo: $rows | positivas: $positive | negativas: $negative".($rows?' | prevalencia: '.number_format($positive/$rows*100,1).'%':'')."\n";echo "Estudiantes distintos: ".count($uniqueStudents)."\n";echo "Pares: ".json_encode($pairs,JSON_UNESCAPED_UNICODE)."\n";echo "Cursos con más filas: ".json_encode(array_slice($courses,0,10,true),JSON_UNESCAPED_UNICODE)."\n";echo "Filas con alguna calificación faltante: $missingGrades\n";echo "Filas sin asistencia en ventana de 30 días: $missingAttendance\n";echo "Filas donde existe fecha académica de evaluación para cruce con asistencia: $dateOverlapAvailable\n";echo "Filas omitidas porque el mismo curso no tiene resultado observable en N+1: $skippedTarget\n";echo "Periodos omitidos por cobertura anormalmente baja: ".($sparse?implode(', ',$sparse):'ninguno')."\n";echo "IMPORTANTE: v7 usa solo información disponible antes del bimestre objetivo; historial previo, evaluaciones, competencias, asistencia y contexto. Nota vacía no es cero; teacher_id no es predictor.\n";
